import subprocess
def run(mode, nullvalue=None):
    cli = ["./executable", ":memory:"]
    inp = f".mode {mode}\n"
    if nullvalue is not None:
        inp += f".nullvalue {nullvalue}\n"
    inp += "create table t(a);\ninsert into t values (NULL);\nselect * from t;\n"
    p=subprocess.run(cli, input=inp, capture_output=True, text=True)
    return p.stdout

for mode in ["list","csv","quote","tabs","ascii","html","json","line","column","box","table","markdown"]:
    for nv in [None, "NULL", "MYNULL", ""]:
        out=run(mode, nv)
        # Represent
        print(f"mode={mode:8} nullvalue={repr(nv):8} => {repr(out[:200])}")

# Also test -nullvalue cli
def run_cli(mode_flag, nv):
    import subprocess
    args=["./executable"]
    if nv is not None:
        args+=["-nullvalue", nv]
    args+=[mode_flag, ":memory:", "create table t(a); insert into t values (NULL); select * from t;"]
    p=subprocess.run(args, capture_output=True, text=True)
    return p.stdout

for mode_flag in ["-list","-csv","-quote","-html","-json"]:
    for nv in [None, "NULL", "MYNULL"]:
        out=run_cli(mode_flag, nv)
