                else:
                    cur+=ch
                    i+=1
                continue
            if in_single:
                if ch=="'":
                    if nxt=="'":
                        cur+=ch+nxt
                        i+=2
                    else:
                        cur+=ch
                        in_single=False
                        i+=1
                    continue
                else:
                    cur+=ch
                    i+=1
                    continue
            if in_double:
                if ch=='"':
                    if nxt=='"':
                        cur+=ch+nxt
                        i+=2
                    else:
                        cur+=ch
                        in_double=False
                        i+=1
                    continue
                else:
                    cur+=ch
                    i+=1
                    continue
            if ch=="'" :
                in_single=True
                cur+=ch
                i+=1
                continue
            if ch=='"':
                in_double=True
                cur+=ch
                i+=1
                continue
            if ch=='-' and nxt=='-':
                in_line_comment=True
                cur+=ch+nxt
                i+=2
                continue
            if ch=='/' and nxt=='*':
                in_block_comment=True
                cur+=ch+nxt
                i+=2
                continue
            if ch==';':
                cur+=ch
                stmts.append(cur)
                cur=""
                i+=1
                continue
            else:
                cur+=ch
                i+=1
        if cur.strip():
            stmts.append(cur)
        return stmts
    def exec_one(self, stmt, is_cli_arg=False, cli_arg_index=None, line_num=None):
        try:
            cur = self.conn.cursor()
            cur.execute(stmt)
            if cur.description is None:
                if self.config.stats:
                    self.print_stats()
                if self.config.timer:
                    self.write_output("Run Time: real 0.000 user 0.000 sys 0.000\n")
                return True
            else:
                rows = cur.fetchall()
                colnames = [d[0] for d in cur.description]
                self.format_output(colnames, rows)
                if self.config.stats:
                    self.print_stats()
                if self.config.timer:
                    self.write_output("Run Time: real 0.000 user 0.000 sys 0.000\n")
                return True
        except sqlite3.Error as e:
            msg = str(e)
            if is_cli_arg:
                n = cli_arg_index if cli_arg_index else 2
                suffix = "th"
                if n % 10 == 1 and n % 100 != 11:
                    suffix = "st"
                elif n % 10 == 2 and n % 100 != 12:
                    suffix = "nd"
                elif n % 10 == 3 and n % 100 != 13:
                    suffix = "rd"
                sys.stderr.write(f"Parse error in {n}{suffix} command line argument: {msg}\n")
            else:
                ln = line_num if line_num else 1
                sys.stderr.write(f"Parse error near line {ln}: {msg}\n")
                if "syntax error" in msg.lower():
                    sys.stderr.write(f"  {stmt}\n")
            return False
        except Exception as e:
            sys.stderr.write(f"Error: {e}\n")
            return False
    def format_output(self, colnames, rows):
        mode = self.config.mode
        headers = self.config.headers
        sep = self.config.colsep
        rowsep = self.config.rowsep
        nullval = self.config.nullvalue
        # helper for value formatting
        def fmt(v):
            if v is None:
                return nullval
            if isinstance(v, bytes):
                try:
                    return v.decode('utf-8')
                except:
                    out=""
                    for b in v:
                        if 0 < b < 32:
                            out+= "^" + chr(b+64)
                        elif b==127:
                            out+= "^?"
                        elif 32 <= b <= 126:
                            out+= chr(b)
                        else:
                            out+= f"\\x{b:02x}"
                    return out
            if isinstance(v, (int, float)):
                return str(v)
            if isinstance(v, str):
                return v
            return str(v)
        out_buf = io.BytesIO()
        def write(s):
            if isinstance(s, str):
                s = s.encode('utf-8')
            out_buf.write(s)
        # Handle each mode
        if mode == "list":
            if headers:
                write(sep.join(colnames) + rowsep)
            for r in rows:
                line = sep.join(fmt(v) for v in r)
                write(line + rowsep)
        elif mode == "csv":
            sio = io.StringIO(newline='')
            writer = csv.writer(sio, delimiter=sep, quotechar='"', quoting=csv.QUOTE_MINIMAL, lineterminator=rowsep)
            if headers:
                writer.writerow(colnames)
            for r in rows:
                vals = [fmt(v) for v in r]
                # csv writer expects strings; for None we already handled via fmt gives nullval
                writer.writerow(vals)
            write(sio.getvalue())
        elif mode == "quote":
            lines = []
            if headers:
                hdr_vals = [f"'{c.replace(chr(39), chr(39)+chr(39))}'" for c in colnames]
                lines.append(sep.join(hdr_vals) + rowsep)
            for r in rows:
                vals = []
                for v in r:
                    if v is None:
                        vals.append(nullval)
                    elif isinstance(v, bytes):
                        vals.append(f"x'{v.hex()}'")
                    elif isinstance(v, str):
                        vals.append(f"'{v.replace(chr(39), chr(39)+chr(39))}'")
                    elif isinstance(v, (int, float)):
                        vals.append(str(v))
                    else:
                        vals.append(str(v))
                lines.append(sep.join(vals) + rowsep)
            write("".join(lines))
        elif mode == "tabs":
            if headers:
                write(sep.join(colnames) + rowsep)
            for r in rows:
                write(sep.join(fmt(v) for v in r) + rowsep)
        elif mode == "ascii":
            if headers:
                write(sep.join(colnames) + rowsep)
            for r in rows:
                write(sep.join(fmt(v) for v in r) + rowsep)
        elif mode == "html":
            if headers:
                write("<TR>\n")
                for c in colnames:
                    write(f"<TH>{self.html_escape(str(c))}\n")
                write("</TR>\n")
            for r in rows:
                write("<TR>\n")
                for v in r:
                    if v is None:
                        write(f"<TD>null\n")
                    else:
                        write(f"<TD>{self.html_escape(fmt(v))}\n")
                write("</TR>\n")
        elif mode == "json":
            objs = []
            for r in rows:
                obj = {}
                for c, v in zip(colnames, r):
                    if v is None:
                        obj[c] = None
                    elif isinstance(v, bytes):
                        try:
                            obj[c] = v.decode('utf-8')
                        except:
