                objs.append(obj)
            j = json.dumps(objs, separators=(',', ':'), ensure_ascii=False)
            if len(objs) > 1:
                j = j.replace("},{", "},\n{")
            write(j + "\n")
        elif mode in ("column","box","table","markdown","line","psql","qbox","tty","split"):
            if mode == "line":
                for idx, r in enumerate(rows):
                    for c, v in zip(colnames, r):
