    def html_escape(self, s):
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    def write_output(self, data, is_echo=False):
        if isinstance(data, str):
            data_b = data.encode('utf-8')
        else:
            data_b = data
        if self.once_file_pending:
            try:
                if self.once_file_pending.startswith("|"):
                    cmd = self.once_file_pending[1:]
                    p = subprocess.Popen(cmd, shell=True, stdin=subprocess.PIPE)
                    p.communicate(data_b)
                else:
                    with open(self.once_file_pending, "wb") as f:
                        f.write(data_b)
                self.once_file_pending = None
                return
            except Exception as e:
                sys.stderr.write(f"Error: cannot write to \"{self.once_file_pending}\": {e}\n")
                self.once_file_pending = None
                return
        if self.current_output_is_file:
            try:
                target = self.current_output
                if isinstance(target, str) and target.startswith("|"):
                    cmd = target[1:]
                    p = subprocess.Popen(cmd, shell=True, stdin=subprocess.PIPE)
                    p.communicate(data_b)
                else:
                    with open(target, "ab") as f:
                        f.write(data_b)
            except Exception as e:
                sys.stderr.write(f"Error: cannot write: {e}\n")
        else:
            try:
                sys.stdout.buffer.write(data_b)
                sys.stdout.buffer.flush()
            except:
                sys.stdout.write(data_b.decode('utf-8', errors='replace'))
                sys.stdout.flush()
