    def handle_dot_command(self, line, line_num):
        cmd_line = line[1:].strip()
        if not cmd_line:
            sys.stderr.write('Error: unknown command or invalid arguments:  "". Enter ".help" for help\n')
            return False
        # split respecting quotes
        try:
            parts = shlex.split(cmd_line, posix=True)
        except:
            parts = cmd_line.split()
        if not parts:
            return True
        cmd = parts[0].lower()
        args = parts[1:]
        if cmd == "help":
            pat = args[0] if args else None
            if pat == "-all":
                pat = None
            print_dot_help(pat)
            return True
        elif cmd == "version":
            sys.stdout.write(DOT_VERSION_STRING + "\n")
            return True
        elif cmd == "mode":
            if not args:
                sys.stdout.write(f".mode {self.config.mode}\n")
                return True
            if args[0] == "--list":
                sys.stdout.write("available modes: " + " ".join(AVAILABLE_MODES) + "\n")
                return True
            mode_name = args[0]
            if mode_name in AVAILABLE_MODES:
                if len(args) > 1:
                    sys.stderr.write(f"line 1: .mode {' '.join(args)}\nline 1: {' ' * (6+len(mode_name)+1)}^--- bad option\nline 1: Use \".help .mode\" for more info\n")
                    return False
                if not self.config.set_mode(mode_name):
                    sys.stderr.write(f"line 1: .mode {mode_name}\nline 1:       ^--- unknown mode\nline 1: Use \".help .mode\" for more info\n")
                    return False
                return True
            else:
                if args[0].startswith("--"):
                    sys.stderr.write(f"line 1: .mode {' '.join(args)}\nline 1:       ^--- bad option\nline 1: Use \".help .mode\" for more info\n")
